-- RRC100: MariaDB10.11, dedicated fresh admin session; manual coordinated application only.
-- Source recipe facts/provenance: batch.public.json. No engine/updater/version/rule changes.
-- Anonymous compound block: no permanent helper procedure or migration table.
DELIMITER //
BEGIN NOT ATOMIC
 DECLARE own_transaction BOOLEAN DEFAULT FALSE;
 DECLARE already_present INT DEFAULT 0;
 DECLARE recipes_before BIGINT DEFAULT 0;
 DECLARE entries_before BIGINT DEFAULT 0;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION
 BEGIN
  IF own_transaction THEN ROLLBACK; END IF;
  RESIGNAL;
 END;
 IF @@in_transaction <> 0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 requires fresh transaction-free session'; END IF;
 IF FIND_IN_SET('STRICT_ALL_TABLES',@@SESSION.sql_mode)=0 AND FIND_IN_SET('STRICT_TRANS_TABLES',@@SESSION.sql_mode)=0 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 strict SQL mode required'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('tradeskill_recipe','tradeskill_recipe_entries','items') AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 InnoDB foundation mismatch'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe')<>16 OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 recipe schema column-count mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc100_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc100_parents LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc100_parent_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc100_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc100_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 START TRANSACTION;
 SET own_transaction=TRUE;
 IF EXISTS(SELECT 1 FROM rrc100_parents e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 existing Fishing recipe drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc100_parent_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc100_parents p ON p.id=r.recipe_id)<>639 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 existing Fishing entries drift'; END IF;
 SELECT COUNT(*) INTO recipes_before FROM tradeskill_recipe;
 SELECT COUNT(*) INTO entries_before FROM tradeskill_recipe_entries;
 SELECT COUNT(*) INTO already_present FROM tradeskill_recipe r JOIN rrc100_recipes e ON r.id=e.id FOR UPDATE;
 IF EXISTS(SELECT 1 FROM rrc100_items e LEFT JOIN items i ON i.id=e.id WHERE i.id IS NULL OR BINARY i.Name<>BINARY e.name) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 item identity/dependency mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=9753 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 17 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=17048 AND `size` <=> 2 AND `itemclass` <=> 1 AND `itemtype` <=> 11 AND `stackable` <=> 0 AND `maxcharges` <=> 0 AND `bagtype` <=> 46 AND `bagslots` <=> 6 AND `bagsize` <=> 2 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=17163 AND `size` <=> 1 AND `itemclass` <=> 1 AND `itemtype` <=> 11 AND `stackable` <=> 0 AND `maxcharges` <=> 0 AND `bagtype` <=> 46 AND `bagslots` <=> 6 AND `bagsize` <=> 3 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=24497 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 17 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=36411 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=36412 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=36413 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=36415 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=36416 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=97267 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=97268 AND `size` <=> 2 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=97269 AND `size` <=> 2 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=97270 AND `size` <=> 2 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=97271 AND `size` <=> 2 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=97272 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=97273 AND `size` <=> 2 AND `itemclass` <=> 0 AND `itemtype` <=> 11 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF (SELECT COUNT(*) FROM items WHERE id=98095 AND `size` <=> 1 AND `itemclass` <=> 0 AND `itemtype` <=> 14 AND `stackable` <=> 1 AND `maxcharges` <=> 0 AND `bagtype` <=> 0 AND `bagslots` <=> 0 AND `bagsize` <=> 0 AND `classes` <=> 65535)<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 native item semantics mismatch'; END IF;
 IF already_present<>12 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 rollback requires exact whole installed batch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc100_recipes e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`name` <=> e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND r.`notes` <=> e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND r.`content_flags` <=> e.`content_flags` AND r.`content_flags_disabled` <=> e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 recipe postimage mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc100_entries e LEFT JOIN tradeskill_recipe_entries r ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE r.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 expected entry absent'; END IF;
 IF EXISTS(SELECT 1 FROM tradeskill_recipe_entries r JOIN rrc100_recipes q ON q.id=r.recipe_id LEFT JOIN rrc100_entries e ON r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer` WHERE e.id IS NULL) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 foreign/different target entries'; END IF;
 IF (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc100_recipes q ON q.id=r.recipe_id)<>72 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 target entry multiplicity mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM char_recipe_list c JOIN rrc100_recipes e ON c.recipe_id=e.id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 rollback refused: learned recipe references exist'; END IF;
 DELETE r FROM tradeskill_recipe_entries r JOIN rrc100_recipes e ON r.recipe_id=e.id;
 DELETE r FROM tradeskill_recipe r JOIN rrc100_recipes e ON r.id=e.id;
 IF (SELECT COUNT(*) FROM tradeskill_recipe)<>recipes_before-12 OR (SELECT COUNT(*) FROM tradeskill_recipe_entries)<>entries_before-72 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 rollback count mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM rrc100_parents e LEFT JOIN tradeskill_recipe r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND BINARY r.`name` <=> BINARY e.`name` AND r.`tradeskill` <=> e.`tradeskill` AND r.`skillneeded` <=> e.`skillneeded` AND r.`trivial` <=> e.`trivial` AND r.`nofail` <=> e.`nofail` AND r.`replace_container` <=> e.`replace_container` AND BINARY r.`notes` <=> BINARY e.`notes` AND r.`must_learn` <=> e.`must_learn` AND r.`learned_by_item_id` <=> e.`learned_by_item_id` AND r.`quest` <=> e.`quest` AND r.`enabled` <=> e.`enabled` AND r.`min_expansion` <=> e.`min_expansion` AND r.`max_expansion` <=> e.`max_expansion` AND BINARY r.`content_flags` <=> BINARY e.`content_flags` AND BINARY r.`content_flags_disabled` <=> BINARY e.`content_flags_disabled`)) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 existing Fishing recipe drift'; END IF;
 IF EXISTS(SELECT 1 FROM rrc100_parent_entries e LEFT JOIN tradeskill_recipe_entries r ON r.id=e.id WHERE r.id IS NULL OR NOT(r.`id` <=> e.`id` AND r.`recipe_id` <=> e.`recipe_id` AND r.`item_id` <=> e.`item_id` AND r.`successcount` <=> e.`successcount` AND r.`failcount` <=> e.`failcount` AND r.`componentcount` <=> e.`componentcount` AND r.`salvagecount` <=> e.`salvagecount` AND r.`iscontainer` <=> e.`iscontainer`)) OR (SELECT COUNT(*) FROM tradeskill_recipe_entries r JOIN rrc100_parents p ON p.id=r.recipe_id)<>639 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC100 existing Fishing entries drift'; END IF;
 DROP TEMPORARY TABLE rrc100_parents;
 DROP TEMPORARY TABLE rrc100_parent_entries;
 DROP TEMPORARY TABLE rrc100_entries;
 DROP TEMPORARY TABLE rrc100_recipes;
 DROP TEMPORARY TABLE rrc100_items;
 COMMIT;
 SET own_transaction=FALSE;
 SELECT 'RRC100' AS batch,already_present AS previous_recipe_count,recipes_before AS recipes_before,(SELECT COUNT(*) FROM tradeskill_recipe) AS recipes_after,entries_before AS entries_before,(SELECT COUNT(*) FROM tradeskill_recipe_entries) AS entries_after,@@in_transaction AS in_transaction;
END//
DELIMITER ;
